package uk.ac.ravensbourne.casevault.service; import com.google.crypto.tink.Aead; import java.nio.file.*; import java.security.*; import java.util.*; import org.apache.tika.Tika; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.crypto.KeysetProvider; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
@Service public class EvidenceService { private final CaseAccessService access; private final AccessPolicy policy; private final CaseRepository cases; private final EvidenceFileRepository files; private final UserAccountRepository users; private final AuditService audit; private final Aead aead; private final Path root; private final Tika tika=new Tika(); public EvidenceService(CaseAccessService a,AccessPolicy p,CaseRepository c,EvidenceFileRepository f,UserAccountRepository u,AuditService au,KeysetProvider k,@Value("${casevault.evidence.directory:uploads}") String dir)throws Exception{access=a;policy=p;cases=c;files=f;users=u;audit=au;aead=k.aead();root=Paths.get(dir).toAbsolutePath();Files.createDirectories(root);} public EvidenceFile upload(UserPrincipal p,UUID caseId,MultipartFile m)throws Exception{var c=access.requireView(p,caseId);if(m.isEmpty()||m.getSize()>10485760)throw new IllegalArgumentException("Evidence rejected");String n=Paths.get(m.getOriginalFilename()==null?"file":m.getOriginalFilename()).getFileName().toString();String ext=n.substring(n.lastIndexOf('.')+1).toLowerCase();byte[] plain=m.getBytes();if(!Map.of("txt","text/plain","pdf","application/pdf","png","image/png").containsKey(ext)||!Map.of("txt","text/plain","pdf","application/pdf","png","image/png").get(ext).equals(tika.detect(plain)))throw new IllegalArgumentException("Evidence rejected");UUID id=UUID.randomUUID(),stored=UUID.randomUUID();Files.write(root.resolve(stored.toString()),aead.encrypt(plain,(caseId+":"+id).getBytes()));var e=files.save(new EvidenceFile(id,c,n,stored,tika.detect(plain),plain.length,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(plain)),users.findById(p.id()).orElseThrow()));audit.record(p,"EVIDENCE_UPLOADED","EVIDENCE",id,"evidence-uploaded");return e;} public byte[] download(UserPrincipal p,UUID caseId,UUID id)throws Exception{var c=access.requireView(p,caseId);var e=files.findByIdAndCaseRecordId(id,caseId).orElseThrow(CaseNotFoundException::new);if(!policy.canDownloadEvidence(p,c,cases.existsAssignment(caseId,p.id())))throw new CaseNotFoundException();return aead.decrypt(Files.readAllBytes(root.resolve(e.getStoredName().toString())),(caseId+":"+id).getBytes());} }
